-- The native core's generators (kp_core.rng, ADR 0008) against vectors from executing the original 1.17.0.1
-- functions (tests/golden/oracle, generated by tools/oracle/export_leaf_vectors.py). Skipped without the kp_core
-- module.
local native_only = require("tests.lua.native_only")
local rng = native_only.rng

local S = {}

local function golden(T, name)
	local text = T.read("tests/golden/oracle/" .. name)
	return assert((loadstring or load)(text))()
end

local TARGET = "94dea44898a3934cdfae2a8149c0044db8ad1af4b4bc54306cdca3b1612d6ed0"

function S.game_raw_golden(T)
	local g = golden(T, "rng_game.lua")
	T.eq(g.target_sha256, TARGET)
	local n = 0
	for _, c in ipairs(g.cases) do
		if c.kind == "raw" then
			local r = rng.game()
			r:seed(c.seed)
			r:set_enabled(c.enabled)
			local result = r:raw(0)
			local o = c.observed
			T.eq(result, o[1], "raw result seed " .. c.seed)
			T.eq(r.state, o[2], "raw state seed " .. c.seed)
			T.eq(r.total, o[3], "raw total seed " .. c.seed)
			T.eq(r.counters[0], o[4], "raw counter seed " .. c.seed)
			n = n + 1
		end
	end
	T.eq(n, 10)
end

function S.game_range_golden(T)
	local g = golden(T, "rng_game.lua")
	local n = 0
	for _, c in ipairs(g.cases) do
		if c.kind == "range" then
			local r = rng.game()
			r:seed(0xFFFFFFFF)
			r:set_enabled(c.enabled)
			local result = r:range(0, c.bounds[1], c.bounds[2])
			local o = c.observed
			local label = ("range [%d,%d] enabled %d"):format(c.bounds[1], c.bounds[2], c.enabled)
			T.eq(result, o[1], label)
			T.eq(r.state, o[2], label)
			T.eq(r.counters[0], o[3], label)
			n = n + 1
		end
	end
	T.eq(n, 12)
end

function S.game_flag_exchange_and_seed(T)
	local r = rng.game(77)
	T.eq(r:set_enabled(1), 0)
	T.eq(r:set_enabled(5), 1)
	T.eq(r.initial_seed, 77)
	r:seed(1)
	r:raw(3); r:raw(3); r:raw(255)
	T.eq(r.total, 3)
	T.eq(r.counters[3], 2)
	T.eq(r.counters[255], 1)
	r:seed(9)
	T.eq(r.total, 0)
	T.eq(r.counters[3], 0)
	T.eq(r.state, 9)
	T.eq(r.initial_seed, 77) -- the live seed is separate from the initial seed
end

function S.portrait_golden(T)
	local g = golden(T, "rng_portrait.lua")
	T.eq(g.target_sha256, TARGET)
	T.eq(#g.cases, 420)
	for i, c in ipairs(g.cases) do
		local p = rng.portrait(c.seed[1], c.seed[2], c.seed[3])
		local v = p:draw(c.low, c.high, c.mask)
		local label = "portrait case " .. i
		T.eq(v, c.actual[1], label)
		T.eq(p.x, c.actual[2], label)
		T.eq(p.y, c.actual[3], label)
		T.eq(p.z, c.actual[4], label)
	end
end

function S.portrait_file_state(T)
	local p = rng.portrait()
	T.eq(p.x, 0x12345678); T.eq(p.y, 0xe9e9e9e9); T.eq(p.z, 0x10934134)
end

-- MSVC rand: the documented sequence for the default seed 1.
function S.crt_sequence(T)
	local c = rng.crt()
	local want = { 41, 18467, 6334, 26500, 19169, 15724, 11478, 29358, 26962, 24464 }
	for i, v in ipairs(want) do T.eq(c:rand(), v, "rand #" .. i) end
	c:srand(0xFFFFFFFF)
	T.eq(c.holdrand, 0xFFFFFFFF)
	c:rand()
	T.eq(c.holdrand, (4294967296 - 214013 + 2531011) % 4294967296)
end

function S.generators_are_independent(T)
	local g, c, p = rng.game(), rng.crt(), rng.portrait()
	g:seed(123); g:set_enabled(1)
	local gs, cs, ps = g.state, c.holdrand, p.x
	c:rand(); p:draw(0, 100, 128)
	T.eq(g.state, gs)
	g:raw(0)
	T.eq(c.holdrand ~= cs, true)
	T.eq(p.x ~= ps, true)
	local c2 = rng.crt(); c2:rand()
	T.eq(c.holdrand, c2.holdrand)
end

function S.snapshot_continuation(T)
	local g, c, p = rng.game(5), rng.crt(9), rng.portrait()
	g:seed(0xDEADBEEF); g:set_enabled(1)
	for i = 1, 1000 do g:range(i % 256, 0, i); c:rand(); p:draw(0, 2, 4) end
	local sg, sc, sp = g:snapshot(), c:snapshot(), p:snapshot()
	local a = {}
	for i = 1, 500 do a[i] = g:raw(i % 7) + c:rand() + p:draw(0, 100, 128) end
	local g2, c2, p2 = rng.game(), rng.crt(), rng.portrait(0, 0, 0)
	g2:restore(sg); c2:restore(sc); p2:restore(sp)
	for i = 1, 500 do T.eq(g2:raw(i % 7) + c2:rand() + p2:draw(0, 100, 128), a[i], "draw " .. i) end
	T.eq(g2.total, g.total)
	T.eq(g2.counters[3], g.counters[3])
end

return native_only.guard(S, "test_rng")
